import{_ as h,o as t,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"AoPS","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/aops.md","filePath":"ideas/aops.md"}'),c={name:"ideas/aops.md"};function o(g,n,e,u,r,l){return t(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="aops" tabindex="-1">AoPS <a class="header-anchor" href="#aops" aria-label="Permalink to &quot;AoPS&quot;">​</a></h1><p>Trên trang này# AoPS — bắt đầu bằng bài toán, không bằng công thức <a href="#aops-—-bat-đau-bang-bai-toan-khong-bang-cong-thuc">​</a> AoPS (Art of Problem Solving) thường bị tóm tắt thành &quot;Toán khó hơn&quot;. Đó là cách hiểu bỏ sót điểm quan trọng nhất. Khác biệt thật nằm ở chỗ khác: Cùng một Knowledge Node, AoPS thiết kế một Learning Experience khác hẳn. Chương trình của họ chạy song song với curriculum phổ thông — từ Prealgebra tới Calculus — nhưng đi sâu hơn về nội dung và về kỹ năng giải quyết vấn đề, nhắm vào học sinh khá giỏi khoảng lớp 5–12. Chủ trương xuyên suốt: để learner <strong>giải vấn đề và tự phát hiện ra kết quả</strong>, thay vì nhận công thức trước rồi luyện áp dụng.</p><h2 id="bai-toan-no-sinh-ra-đe-giai-​" tabindex="-1">Bài toán nó sinh ra để giải <a href="#bai-toan-no-sinh-ra-đe-giai">​</a> <a class="header-anchor" href="#bai-toan-no-sinh-ra-đe-giai-​" aria-label="Permalink to &quot;Bài toán nó sinh ra để giải [​](#bai-toan-no-sinh-ra-đe-giai)&quot;">​</a></h2><p>Một học sinh làm 200 bài cùng dạng sẽ rất nhanh và rất chính xác ở dạng đó. Nhưng gặp một bài chưa từng thấy, em ấy không biết bắt đầu từ đâu — vì trong suốt 200 bài kia, <strong>chưa lần nào em phải tự chọn công cụ</strong>. Đề bài đã luôn nói sẵn dùng phương pháp gì. AoPS nhắm thẳng vào khoảng trống đó.</p><h2 id="bon-vi-du-cung-mot-node-hai-cach-day-​" tabindex="-1">Bốn ví dụ: cùng một node, hai cách dạy <a href="#bon-vi-du-cung-mot-node-hai-cach-day">​</a> <a class="header-anchor" href="#bon-vi-du-cung-mot-node-hai-cach-day-​" aria-label="Permalink to &quot;Bốn ví dụ: cùng một node, hai cách dạy [​](#bon-vi-du-cung-mot-node-hai-cach-day)&quot;">​</a></h2><h3 id="_1-·-đat-nhan-tu-chung-​" tabindex="-1">1 · Đặt nhân tử chung <a href="#_1-·-đat-nhan-tu-chung">​</a> <a class="header-anchor" href="#_1-·-đat-nhan-tu-chung-​" aria-label="Permalink to &quot;1 · Đặt nhân tử chung [​](#_1-·-đat-nhan-tu-chung)&quot;">​</a></h3><p>Node: Cách quen thuộcThầy nêu: &quot;Muốn phân tích đa thức thành nhân tử bằng phương pháp đặt nhân tử chung, ta tìm nhân tử chung của các hạng tử.&quot; Làm mẫu , rồi học sinh làm , , … Sau 20 bài là thành thạo. Mục tiêu ngầm: nhìn ra dạng → nhớ phương pháp → làm đúng. Tinh thần AoPSBắt đầu bằng một phép tính: — &quot;Có cách nào nhanh hơn tính từng phép nhân không?&quot; Learner tự ra . Rồi . Rồi tới — cộng không được nữa. &quot;Vẫn dùng được tính chất phân phối chứ?&quot; Learner thử: . Đến lúc này khái niệm &quot;nhân tử chung&quot; mới xuất hiện — như một thứ learner vừa tìm ra.</p><h3 id="_2-·-phuong-trinh-bac-nhat-​" tabindex="-1">2 · Phương trình bậc nhất <a href="#_2-·-phuong-trinh-bac-nhat">​</a> <a class="header-anchor" href="#_2-·-phuong-trinh-bac-nhat-​" aria-label="Permalink to &quot;2 · Phương trình bậc nhất [​](#_2-·-phuong-trinh-bac-nhat)&quot;">​</a></h3><p>Node: giải Cách quen thuộc: thầy giới thiệu → chuyển vế → , kèm quy tắc <strong>&quot;chuyển vế đổi dấu&quot;</strong>. Học sinh làm 20 phương trình, rất nhanh. Tinh thần AoPS: vẫn bài đó, nhưng hỏi <em>&quot;nếu không biết bất kỳ quy tắc chuyển vế nào, con làm gì để phương trình vẫn đúng?&quot;</em> textTrừ 5 ở cả hai vế: 3x + 5 − 5 = 20 − 5 → 3x = 15 Chia 3 ở cả hai vế: 3x ÷ 3 = 15 ÷ 3 → x = 5Vài bài sau mới tổng quát hoá thành . Learner không dừng ở <em>&quot;chuyển vế thì đổi dấu&quot;</em>, mà hiểu điều nằm dưới nó: <strong>phương trình là một quan hệ bất biến — làm cùng một phép lên hai phía thì đẳng thức được bảo toàn.</strong> Quy tắc chuyển vế trở thành hệ quả, không phải luật trời.</p><h3 id="_3-·-tong-ba-goc-tam-giac-​" tabindex="-1">3 · Tổng ba góc tam giác <a href="#_3-·-tong-ba-goc-tam-giac">​</a> <a class="header-anchor" href="#_3-·-tong-ba-goc-tam-giac-​" aria-label="Permalink to &quot;3 · Tổng ba góc tam giác [​](#_3-·-tong-ba-goc-tam-giac)&quot;">​</a></h3><p>Node: Cách quen thuộc: thầy phát biểu định lý, cho , học sinh tìm , rồi luyện tập. Tinh thần AoPS: cho một tam giác bất kỳ và hỏi <em>&quot;không dùng định lý tổng ba góc, con có tìm được quan hệ giữa ba góc này không?&quot;</em> Learner vẽ đường song song qua một đỉnh, dùng góc so le trong, ghép ba góc lại và thấy chúng tạo thành một góc bẹt. Định lý xuất hiện sau. Rồi câu tiếp theo biến node này thành bệ phóng cho node sau: Một đa giác cạnh thì tổng các góc bằng bao nhiêu? Learner chia đa giác thành tam giác và tự ra .</p><h3 id="_4-·-ty-le-​" tabindex="-1">4 · Tỷ lệ <a href="#_4-·-ty-le">​</a> <a class="header-anchor" href="#_4-·-ty-le-​" aria-label="Permalink to &quot;4 · Tỷ lệ [​](#_4-·-ty-le)&quot;">​</a></h3><p>Node: Cách quen thuộc: cho , dạy <strong>nhân chéo</strong> → → . Learner học được: <em>&quot;gặp tỷ lệ thì nhân chéo.&quot;</em> Tinh thần AoPS: chưa cho nhân chéo. Hỏi bằng tình huống thật — <em>&quot;công thức pha nước cam dùng 3 cốc cam cho 5 cốc nước. Nếu dùng 20 cốc nước thì cần bao nhiêu cốc cam?&quot;</em> Learner thấy là gấp 4, nên . Rồi đưa . Lúc này phép gấp không còn đẹp nữa, learner buộc phải xây một cách tổng quát — và từ đó mới rút ra . <strong>Nhân chéo từ một mẹo trở thành hệ quả của đại số.</strong></p><h2 id="hai-trinh-tu-​" tabindex="-1">Hai trình tự <a href="#hai-trinh-tu">​</a> <a class="header-anchor" href="#hai-trinh-tu-​" aria-label="Permalink to &quot;Hai trình tự [​](#hai-trinh-tu)&quot;">​</a></h2><p>textQuen thuộc: định nghĩa → công thức → ví dụ → bài tập AoPS: bài toán → vật lộn → thấy quy luật → phỏng đoán → giải thích → tổng quát hoá</p><h2 id="bang-đoi-chieu-​" tabindex="-1">Bảng đối chiếu <a href="#bang-đoi-chieu">​</a> <a class="header-anchor" href="#bang-đoi-chieu-​" aria-label="Permalink to &quot;Bảng đối chiếu [​](#bang-đoi-chieu)&quot;">​</a></h2><p>Luyện dạng truyền thốngAoPSBắt đầu từCông thức, quy tắcBài toánThầy côGiải thích cách làmĐặt tình huốngLearnerLàm theoTự tìm đườngSaiCần sửaLà dữ liệu để khám pháBài tậpCủng cố phương phápLàm lộ ra ý tưởng toán họcMục tiêuLàm đúng dạngHiểu cấu trúcChuyển sang bài mớiBài tương tựBài chưa từng thấyTăng độ khó bằngTính toán nặng hơnLập luận sâu hơnCông thứcCó trướcThường được hình thức hoá sauThành công nghĩa là&quot;Biết làm&quot;&quot;Biết nghĩ&quot;</p><h2 id="khi-đe-bai-đa-tiet-lo-chien-luoc-​" tabindex="-1">Khi đề bài đã tiết lộ chiến lược <a href="#khi-đe-bai-đa-tiet-lo-chien-luoc">​</a> <a class="header-anchor" href="#khi-đe-bai-đa-tiet-lo-chien-luoc-​" aria-label="Permalink to &quot;Khi đề bài đã tiết lộ chiến lược [​](#khi-đe-bai-đa-tiet-lo-chien-luoc)&quot;">​</a></h2><p>Đây là chi tiết đáng chú ý nhất, và cũng dễ bị bỏ qua nhất. Một người giải toán thật sự phải giải <strong>hai</strong> bài toán, theo thứ tự:</p><ul><li><strong>Nên làm gì?</strong></li><li><strong>Làm có đúng không?</strong> Đề bài phổ thông thường ghi sẵn <em>&quot;giải phương trình bằng phương pháp…&quot;</em> — và như vậy bài toán thứ nhất đã bị lấy mất. Ví dụ: . Nếu đề nói <em>&quot;đặt t = x²&quot;</em> thì phần khó nhất coi như xong. Cái còn lại chỉ là tính toán. Tương tự, một bài ghi <em>&quot;hãy phân tích bằng phương pháp đặt nhân tử chung&quot;</em> đã tự tiết lộ chiến lược. So với việc chỉ đưa và để learner tự nhận ra phải nhóm lại: textKhả năng <strong>chọn chiến lược khi chưa ai chỉ chiến lược</strong> chính là thứ AoPS theo đuổi.</li></ul><h2 id="khong-co-ben-nao-te-​" tabindex="-1">Không có bên nào tệ <a href="#khong-co-ben-nao-te">​</a> <a class="header-anchor" href="#khong-co-ben-nao-te-​" aria-label="Permalink to &quot;Không có bên nào tệ [​](#khong-co-ben-nao-te)&quot;">​</a></h2><p>Hai hệ thống đang tối ưu cho hai mục tiêu khác nhau, và cả hai mục tiêu đều có thật. Luyện dạng mạnh ởTốc độ · kỹ thuật · nhận dạng khuôn mẫu · khối lượng bài · thành tích phòng thi · sự thành thục quy trình. Nếu còn ba tuần nữa thi và đề đi theo dạng quen thuộc, đây là cách hiệu quả nhất. Không có gì phải xin lỗi về điều đó. AoPS mạnh ởLập luận · khám phá · chuyển sang bài lạ · chọn chiến lược · thấy cấu trúc toán học · vật lộn có ích · tổng quát hoá · chứng minh · hiểu bản chất. Ở các lớp cao hơn, AoPS còn nhấn mạnh tính chặt chẽ và trừu tượng — học sinh bắt đầu viết chứng minh hình thức từ khá sớm. Cái giá của AoPS là <strong>thời gian</strong>. Một node dạy theo lối khám phá tốn gấp hai tới ba lần. Với learner chưa có nền, hoặc với learner còn vài ngày nữa thi, đó là cái giá không trả nổi.</p><h2 id="nemo12-khong-chon-mot-trong-hai-​" tabindex="-1">Nemo12 không chọn một trong hai <a href="#nemo12-khong-chon-mot-trong-hai">​</a> <a class="header-anchor" href="#nemo12-khong-chon-mot-trong-hai-​" aria-label="Permalink to &quot;Nemo12 không chọn một trong hai [​](#nemo12-khong-chon-mot-trong-hai)&quot;">​</a></h2><p>Kết luận đáng giá nhất từ AoPS không phải &quot;hãy dạy như AoPS&quot;, mà là một nguyên tắc kiến trúc: Knowledge Node không nên chứa &quot;cách dạy&quot;. Cùng một node có thể có nhiều Learning Experience khác nhau, và việc chọn cái nào là quyết định về <strong>learner này, lúc này</strong>. <a href="/decisions/cach-day">Xem Nemo12 chọn cách dạy thế nào →</a> AoPS không dạy Toán khó hơn. Nó dạy cùng nội dung đó theo một trình tự khác — và trình tự mới là thứ tạo ra người biết nghĩ. <a href="/ideas/inquiry-based">Inquiry-based Learning →</a></p>',24)])])}const d=h(c,[["render",o]]);export{b as __pageData,d as default};
